INSERT INTO system_role_menu(role_id,menu_id,tenant_id) SELECT 1,m.id,1 FROM system_menu m JOIN system_role r ON r.id=1 AND r.tenant_id=1 AND r.code='tenant_admin' AND r.deleted=0 WHERE m.deleted=0 AND m.permission IN ('trade:after-sale:agree','trade:after-sale:disagree','trade:after-sale:query','trade:after-sale:receive','trade:after-sale:refund','trade:after-sale:refuse','trade:brokerage-record:query','trade:brokerage-user:clear-bind-user','trade:brokerage-user:create','trade:brokerage-user:query','trade:brokerage-user:update-bind-user','trade:brokerage-user:update-brokerage-enable','trade:brokerage-withdraw:approve','trade:brokerage-withdraw:query','trade:brokerage-withdraw:reject','trade:brokerage-withdraw:update-transferred','trade:config:query','trade:config:save','trade:delivery:express-template:create','trade:delivery:express-template:delete','trade:delivery:express-template:query','trade:delivery:express-template:update','trade:delivery:express:create','trade:delivery:express:delete','trade:delivery:express:query','trade:delivery:express:update','trade:delivery:pick-up-store:bind','trade:delivery:pick-up-store:create','trade:delivery:pick-up-store:delete','trade:delivery:pick-up-store:query','trade:delivery:pick-up-store:update','trade:order:delivery','trade:order:pick-up-by-id','trade:order:pick-up-by-verify-code','trade:order:query','trade:order:update-address','trade:order:update-price','trade:order:update-remark') AND NOT EXISTS (SELECT 1 FROM system_role_menu rm WHERE rm.role_id=1 AND rm.menu_id=m.id AND rm.tenant_id=1 AND rm.deleted=0);
